c={'goalId':'4c7c7297-b4bb-56cd-bbfe-85d4cdb784e8','ownWholeResponses':{'cash-flow-stress':'Eigenkapital belastet die Firma nicht mit vereinbarten Zins- und Rückzahlungsraten, doch neue Eigentümer können Mitsprache erhalten. Kredit vermeidet Anteilsabgabe, aber Zins und Rückzahlung belasten die Firma; deshalb muss man kritisch bleiben. Ich prüfe die vorliegenden Zahlen weder im Plan noch im schwachen Szenario und begründe keine Entscheidung daran.','guarantee-risk':'Eine Bürgschaft ist gefährlich, auch bei einer Gesellschaft mit begrenzter Haftung sollte man sie kritisch diskutieren. Ohne Bürgschaft trägt man weniger Risiko. Ich unterscheide hier ausdrücklich nicht Beteiligungsverlust und die zusätzliche persönliche Einstandspflicht und prüfe keinen Haftungsumfang.'},'comparison':{'vagueCriticalDiscussionPossible':True,'wholeCurrentPFinancialStressAndRiskSeparationShown':False,'notExamScore':True},'scope':'Concrete clarity failure, not a claimed actual learner submission or legal advice.'};q=W/'actual-own-whole-critical-label-without-payment-risk-comparison-counterexample.json';assert not q.exists();q.write_text(json.dumps(c,ensure_ascii=False,indent=2)+'\n')
